16	
17	// validSegment matches a single path segment: starts with alphanumeric,
18	// followed by alphanumeric, dots, underscores, or hyphens.
19	var validSegment = regexp.MustCompile(`^[a-zA-Z0-9][a-zA-Z0-9._-]*$`)
20	
21	// validateSegments returns false if any segment contains characters outside
22	// the allowed set, guarding against path traversal and injection.
23	func validateSegments(segments []string) bool {
24		for _, s := range segments {
25			if !validSegment.MatchString(s) {
26				return false
27			}
28		}
29		return true
30	}
31	
32	// gzipMagic is the two-byte header for gzip files.
33	var gzipMagic = []byte{0x1f, 0x8b}
34	
35	type Handler struct {
36		store         storage.Client
37		presignExpiry time.Duration
38		maxUploadSize int64
39		rwPassed      atomic.Bool
40	}
41	
42	func NewHandler(store storage.Client, presignExpiry time.Duration, maxUploadSize int64) *Handler {
43		return &Handler{store: store, presignExpiry: presignExpiry, maxUploadSize: maxUploadSize}
44	}
45	
46	func (h *Handler) Register(e *echo.Echo) {
47		e.GET("/.well-known/terraform.json", h.ServiceDiscovery)
48		e.GET("/v1/modules/*", h.moduleGET)
49		e.PUT("/v1/modules/*", h.Upload)
50		e.GET("/health", h.Health)
51		e.GET("/livez", h.Livez)
52		e.GET("/readyz", h.Readyz)
53	}
54	
55	// moduleGET dispatches GET requests under /v1/modules/ based on the path suffix.
56	func (h *Handler) moduleGET(c echo.Context) error {
57		path := c.Param("*")
58		if strings.HasSuffix(path, "/versions") {
59			return h.ListVersions(c)
60		}
61		if strings.HasSuffix(path, "/download") {
62			return h.Download(c)
63		}
64		return c.JSON(http.StatusNotFound, map[string]string{"error": "path must end in /versions or /download"})
65	}
66	
67	// parsePathSegments splits a URL path string into non-empty segments.
68	func parsePathSegments(path string) []string {
69		parts := strings.Split(path, "/")
70		segments := make([]string, 0, len(parts))
71		for _, p := range parts {
72			if p != "" {
73				segments = append(segments, p)
74			}
75		}
76		return segments
77	}
78	
79	func (*Handler) Health(c echo.Context) error {
80		return c.NoContent(http.StatusOK)
81	}
82	
83	func (*Handler) Livez(c echo.Context) error {
84		return c.NoContent(http.StatusOK)
85	}
86	
87	func (h *Handler) Readyz(c echo.Context) error {
88		ctx := c.Request().Context()
89	
90		if err := h.store.HeadBucket(ctx); err != nil {
91			c.Logger().Errorf("readyz: %v", err)
92			return c.JSON(http.StatusServiceUnavailable, map[string]string{"error": "head bucket check failed"})
93		}
94	
95		if !h.rwPassed.Load() {
96			if err := h.store.CheckReadWrite(ctx); err != nil {
97				c.Logger().Errorf("readyz: %v", err)
98				return c.JSON(http.StatusServiceUnavailable, map[string]string{"error": "read/write check failed"})
99			}
100			h.rwPassed.Store(true)
101		}
102	
103		return c.NoContent(http.StatusOK)
104	}
105	
106	func (*Handler) ServiceDiscovery(c echo.Context) error {
107		return c.JSON(http.StatusOK, map[string]string{
108			"modules.v1": "/v1/modules/",
109		})
110	}
111	
112	type versionEntry struct {
113		Version string `json:"version"`
114	}
115	
116	// ListVersions handles GET /v1/modules/{modulePath...}/versions.
117	// modulePath must have at least two segments (e.g. namespace/name/provider).
118	func (h *Handler) ListVersions(c echo.Context) error {
119		raw := strings.TrimSuffix(c.Param("*"), "/versions")
120		modulePath := parsePathSegments(raw)
121		if len(modulePath) < 2 || !validateSegments(modulePath) {
122			return c.JSON(http.StatusBadRequest, map[string]string{"error": "invalid module path"})
123		}
124	
125		versions, err := h.store.ListVersions(c.Request().Context(), modulePath)
126		if err != nil {
127			c.Logger().Errorf("failed to list versions: %v", err)
128			return c.JSON(http.StatusInternalServerError, map[string]string{"error": "internal server error"})
129		}
130	
131		if len(versions) == 0 {
132			return c.JSON(http.StatusNotFound, map[string]string{"error": "module not found"})
133		}
134	
135		entries := make([]versionEntry, len(versions))
136		for i, v := range versions {
137			entries[i] = versionEntry{Version: v}
138		}
139	
140		resp := map[string]any{
141			"modules": []map[string]any{
142				{"versions": entries},
143			},
144		}
145	
146		return c.JSON(http.StatusOK, resp)
147	}
148	
149	// Download handles GET /v1/modules/{modulePath...}/{version}/download.
150	// The path must have at least three segments so that modulePath has at least
151	// two elements and version is non-empty.
152	func (h *Handler) Download(c echo.Context) error {
153		raw := strings.TrimSuffix(c.Param("*"), "/download")
154		segments := parsePathSegments(raw)
155		if len(segments) < 3 || !validateSegments(segments) {
156			return c.JSON(http.StatusBadRequest, map[string]string{"error": "invalid module path"})
157		}
158		modulePath := segments[:len(segments)-1]
159		version := segments[len(segments)-1]
160	
161		ctx := c.Request().Context()
162	
163		exists, err := h.store.HeadModule(ctx, modulePath, version)
164		if err != nil {
165			c.Logger().Errorf("failed to check module existence: %v", err)
166			return c.JSON(http.StatusInternalServerError, map[string]string{"error": "internal server error"})
167		}
168	
169		if !exists {
170			return c.JSON(http.StatusNotFound, map[string]string{"error": "module version not found"})
171		}
172	
173		url, err := h.store.PresignGetModule(ctx, modulePath, version, h.presignExpiry)
174		if err != nil {
175			c.Logger().Errorf("failed to generate presigned URL: %v", err)
176			return c.JSON(http.StatusInternalServerError, map[string]string{"error": "internal server error"})
177		}
178	
179		c.Response().Header().Set("X-Terraform-Get", url)
180		return c.NoContent(http.StatusNoContent)
181	}
182	
183	// Upload handles PUT /v1/modules/{modulePath...}/{version}.
184	// The path must have at least three segments so that modulePath has at least
185	// two elements and version is non-empty.
186	//
187	// The existence check and write are not atomic (TOCTOU): a concurrent upload
188	// between HeadModule and PutModule could result in a silent overwrite because
189	// S3 PutObject is last-write-wins. Conditional writes (If-None-Match) are not
190	// universally supported across S3-compatible backends, so we accept this trade-off.
191	func (h *Handler) Upload(c echo.Context) error {
192		segments := parsePathSegments(c.Param("*"))
193		if len(segments) < 3 || !validateSegments(segments) {
194			return c.JSON(http.StatusBadRequest, map[string]string{"error": "invalid module path"})
195		}
196		modulePath := segments[:len(segments)-1]
197		version := segments[len(segments)-1]
198	
199		ctx := c.Request().Context()
200	
201		exists, err := h.store.HeadModule(ctx, modulePath, version)
202		if err != nil {
203			c.Logger().Errorf("failed to check module existence: %v", err)
204			return c.JSON(http.StatusInternalServerError, map[string]string{"error": "internal server error"})
205		}
206		if exists {
207			return c.JSON(http.StatusConflict, map[string]string{"error": "module version already exists"})
208		}
209	
210		body := http.MaxBytesReader(c.Response(), c.Request().Body, h.maxUploadSize)
211		defer body.Close()
212	
213		header := make([]byte, len(gzipMagic))
214		if _, err := io.ReadFull(body, header); err != nil {
215			return c.JSON(http.StatusBadRequest, map[string]string{"error": "request body is too small or empty"})
216		}
217		if header[0] != gzipMagic[0] || header[1] != gzipMagic[1] {
218			return c.JSON(http.StatusBadRequest, map[string]string{"error": "request body is not a valid gzip archive"})
219		}
220	
221		// Buffer the full body so S3 PutObject gets a seekable reader, which the
222		// AWS SDK requires for checksum computation over non-TLS connections.
223		// This is bounded by MaxBytesReader so memory usage is capped at maxUploadSize.
224		rest, err := io.ReadAll(body)
225		if err != nil {
226			var maxBytesErr *http.MaxBytesError
227			if errors.As(err, &maxBytesErr) {
228				return c.JSON(http.StatusBadRequest, map[string]string{"error": "request body exceeds maximum upload size"})
229			}
230			return c.JSON(http.StatusBadRequest, map[string]string{"error": "failed to read request body"})
231		}
232		full := append(header, rest...)
233		if err := h.store.PutModule(ctx, modulePath, version, bytes.NewReader(full)); err != nil {
234			c.Logger().Errorf("failed to store module: %v", err)
235			return c.JSON(http.StatusInternalServerError, map[string]string{"error": "internal server error"})
236		}
237	
238		return c.NoContent(http.StatusCreated)
239	}
