13	
14	const defaultAPIBaseURL = "https://api.github.com"
15	
16	// APIError represents a non-2xx response from the GitHub API.
17	type APIError struct {
18		StatusCode int
19		Body       string
20	}
21	
22	func (e *APIError) Error() string {
23		return fmt.Sprintf("github API returned status %d: %s", e.StatusCode, e.Body)
24	}
25	
26	// RateLimitError is returned when the GitHub API rate limit is exceeded.
27	// It wraps APIError so callers using errors.As with *APIError still match.
28	type RateLimitError struct {
29		*APIError
30		ResetAt time.Time
31	}
32	
33	func (e *RateLimitError) Error() string {
34		return fmt.Sprintf("github API rate limited (resets at %s): %s", e.ResetAt.Format(time.RFC3339), e.APIError.Error())
35	}
36	
37	func (e *RateLimitError) Unwrap() error {
38		return e.APIError
39	}
