41	type PullRequestInput struct {
42		BaseURL string
43		Repo    string
44		Base    string
45		Head    string
46		Title   string
47		Body    string
48		Token   string
49	}
50	
51	type createPullRequestRequest struct {
52		Title string `json:"title"`
53		Head  string `json:"head"`
54		Base  string `json:"base"`
55		Body  string `json:"body"`
56	}
57	
58	type createPullRequestResponse struct {
59		HTMLURL string `json:"html_url"`
60	}
61	
62	// CommitPRsInput holds parameters for listing PRs associated with a commit.
63	type CommitPRsInput struct {
64		BaseURL string
65		Repo    string
66		SHA     string
67		Token   string
68	}
69	
70	// CommitPullRequest represents a pull request returned by the commit PRs endpoint.
71	type CommitPullRequest struct {
72		Number  int    `json:"number"`
73		Title   string `json:"title"`
74		HTMLURL string `json:"html_url"`
75		User    PRUser `json:"user"`
76	}
77	
78	// PRUser represents the user who authored a pull request.
79	type PRUser struct {
80		Login string `json:"login"`
81	}
82	
83	// ListPullRequestsForCommit returns the pull requests associated with a commit SHA.
84	// Uses: GET /repos/{owner}/{repo}/commits/{sha}/pulls
85	func ListPullRequestsForCommit(ctx context.Context, httpClient *http.Client, input CommitPRsInput) ([]CommitPullRequest, error) {
86		if strings.TrimSpace(input.Token) == "" {
87			return nil, fmt.Errorf("github token is required")
88		}
89		if strings.TrimSpace(input.Repo) == "" || !strings.Contains(input.Repo, "/") {
90			return nil, fmt.Errorf("repo must be in owner/name format")
91		}
92		if strings.TrimSpace(input.SHA) == "" {
93			return nil, fmt.Errorf("commit SHA is required")
94		}
95	
96		baseURL := input.BaseURL
97		if baseURL == "" {
98			baseURL = defaultAPIBaseURL
99		}
100	
101		endpoint := fmt.Sprintf("%s/repos/%s/commits/%s/pulls", strings.TrimRight(baseURL, "/"), input.Repo, input.SHA)
102		req, err := http.NewRequestWithContext(ctx, http.MethodGet, endpoint, nil)
103		if err != nil {
104			return nil, fmt.Errorf("failed to create request: %w", err)
105		}
106		req.Header.Set("Accept", "application/vnd.github+json")
107		req.Header.Set("Authorization", "Bearer "+input.Token)
108	
109		if httpClient == nil {
110			httpClient = http.DefaultClient
111		}
112		resp, err := httpClient.Do(req)
113		if err != nil {
114			return nil, fmt.Errorf("failed to list PRs for commit %s: %w", input.SHA, err)
115		}
116		defer resp.Body.Close()
117	
118		if resp.StatusCode < 200 || resp.StatusCode >= 300 {
119			body, _ := io.ReadAll(resp.Body)
120			return nil, &APIError{StatusCode: resp.StatusCode, Body: strings.TrimSpace(string(body))}
121		}
122	
123		var prs []CommitPullRequest
124		if err := json.NewDecoder(resp.Body).Decode(&prs); err != nil {
125			return nil, fmt.Errorf("failed to decode PR list response: %w", err)
126		}
127	
128		return prs, nil
129	}
130	
131	func CreatePullRequest(ctx context.Context, httpClient *http.Client, input PullRequestInput) (string, error) {
132		if strings.TrimSpace(input.Token) == "" {
133			return "", fmt.Errorf("github token is required")
134		}
135		if strings.TrimSpace(input.Repo) == "" || !strings.Contains(input.Repo, "/") {
136			return "", fmt.Errorf("repo must be in owner/name format")
137		}
138		if strings.TrimSpace(input.Base) == "" || strings.TrimSpace(input.Head) == "" {
139			return "", fmt.Errorf("base and head branches are required")
140		}
141	
142		baseURL := input.BaseURL
143		if baseURL == "" {
144			baseURL = defaultAPIBaseURL
145		}
146	
147		reqBody := createPullRequestRequest{
148			Title: input.Title,
149			Head:  input.Head,
150			Base:  input.Base,
151			Body:  input.Body,
152		}
153		payload, err := json.Marshal(reqBody)
154		if err != nil {
155			return "", fmt.Errorf("failed to marshal PR request: %w", err)
156		}
157	
158		endpoint := fmt.Sprintf("%s/repos/%s/pulls", strings.TrimRight(baseURL, "/"), input.Repo)
159		req, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint, bytes.NewReader(payload))
160		if err != nil {
161			return "", fmt.Errorf("failed to create PR request: %w", err)
162		}
163		req.Header.Set("Accept", "application/vnd.github+json")
164		req.Header.Set("Authorization", "Bearer "+input.Token)
165		req.Header.Set("Content-Type", "application/json")
166	
167		if httpClient == nil {
168			httpClient = http.DefaultClient
169		}
170		resp, err := httpClient.Do(req)
171		if err != nil {
172			return "", fmt.Errorf("failed to create pull request: %w", err)
173		}
174		defer resp.Body.Close()
175	
176		if resp.StatusCode < 200 || resp.StatusCode >= 300 {
177			body, _ := io.ReadAll(resp.Body)
178			return "", &APIError{StatusCode: resp.StatusCode, Body: strings.TrimSpace(string(body))}
179		}
180	
181		var pr createPullRequestResponse
182		if err := json.NewDecoder(resp.Body).Decode(&pr); err != nil {
183			return "", fmt.Errorf("failed to decode PR response: %w", err)
184		}
185		if strings.TrimSpace(pr.HTMLURL) == "" {
186			return "", fmt.Errorf("github API response missing html_url")
187		}
188	
189		return pr.HTMLURL, nil
190	}
